from solution import sequence


def test_issue_example_10():
    """Example: sequence(10) == 6."""
    assert sequence(10) == 6  # a(10)=a(5)+a(5)=3+3=6


def test_issue_first_number():
    """Base case: the 1st Newman-Conway number is 1."""
    assert sequence(1) == 1  # base a(1)=1


def test_issue_second_number():
    """Base case: the 2nd Newman-Conway number is 1."""
    assert sequence(2) == 1  # base a(2)=1


def test_issue_third_number():
    """Recurrence: the 3rd Newman-Conway number is 2."""
    assert sequence(3) == 2  # a(1)+a(2)=1+1=2


def test_issue_fourth_number():
    """Recurrence: the 4th Newman-Conway number is 2."""
    assert sequence(4) == 2  # a(2)+a(2)=1+1=2


def test_issue_fifth_number():
    """Recurrence: the 5th Newman-Conway number is 3."""
    assert sequence(5) == 3  # a(2)+a(3)=1+2=3


def test_issue_sixth_number():
    """Recurrence: the 6th Newman-Conway number is 4."""
    assert sequence(6) == 4  # a(3)+a(3)=2+2=4


def test_issue_ninth_number():
    """Recurrence: the 9th Newman-Conway number is 5."""
    assert sequence(9) == 5  # a(4)+a(5)=2+3=5


def test_issue_thirteenth_number():
    """Recurrence: the 13th Newman-Conway number is 8."""
    assert sequence(13) == 8  # a(7)+a(6)=4+4=8


def test_issue_twentieth_number():
    """Recurrence: the 20th Newman-Conway number is 12."""
    assert sequence(20) == 12  # a(11)+a(9)=7+5=12


def test_contract_returns_int():
    """Contract: sequence returns the n-th number as an int."""
    assert isinstance(sequence(10), int)  # sequence(10)=6, 6 is int: 3+3=6


def test_contract_is_deterministic():
    """Contract: sequence finds the same n-th number on repeated calls."""
    assert sequence(10) == sequence(10)  # both calls give 6: 3+3=6
